package com.carvo.app;

import android.content.Context;
import android.net.Uri;

import java.io.BufferedInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.zip.GZIPInputStream;

/**
 * Zero-dependency reader and local storage helper for CMAP1 offline vector packs
 * generated by corvo-map-cutter.html.
 */
public class CroMapPack {

    public static final int KIND_WATER_POLY = 0x01;
    public static final int KIND_PARK_POLY  = 0x02;
    public static final int KIND_WATERWAY   = 0x03;
    public static final int KIND_BUILDING   = 0x04;
    public static final int KIND_HIGHWAY    = 0x10;
    public static final int KIND_MAJOR_ROAD = 0x11;
    public static final int KIND_MINOR_ROAD = 0x12;
    public static final int KIND_PATH       = 0x13;
    public static final int KIND_RAIL       = 0x14;
    public static final int KIND_PLACE_LBL  = 0x20;
    public static final int KIND_ROAD_LBL   = 0x21;

    public static final int GTYPE_POINT = 0;
    public static final int GTYPE_LINE  = 1;
    public static final int GTYPE_POLY  = 2;

    private static final String FILE_NAME = "corvo_area.cmap";

    public static final class Feature {
        public final int kind;
        public final int gtype;
        public final String label;
        public final short[][] rings; // each ring: interleaved [x0, y0, x1, y1, ...]

        public Feature(int kind, int gtype, String label, short[][] rings) {
            this.kind = kind;
            this.gtype = gtype;
            this.label = label;
            this.rings = rings;
        }
    }

    public static final class Tile {
        public final int tx;
        public final int ty;
        public final int tz;
        public final Feature[] features;

        public Tile(int tx, int ty, int tz, Feature[] features) {
            this.tx = tx;
            this.ty = ty;
            this.tz = tz;
            this.features = features;
        }
    }

    public final int zoom;
    public final int minX;
    public final int minY;
    public final int cols;
    public final int rows;
    public final float minLat;
    public final float minLon;
    public final float maxLat;
    public final float maxLon;
    public final String areaName;
    public final float[] cropPoly; // interleaved [lat0, lon0, ...] when version >= 2, else null
    public final int tileCount;
    public final int totalFeatures;
    public final long fileBytes;
    private final HashMap<Long, Tile> tiles;

    private CroMapPack(int zoom, int minX, int minY, int cols, int rows,
                       float minLat, float minLon, float maxLat, float maxLon,
                       String areaName, float[] cropPoly, int tileCount, int totalFeatures,
                       long fileBytes, HashMap<Long, Tile> tiles) {
        this.zoom = zoom;
        this.minX = minX;
        this.minY = minY;
        this.cols = cols;
        this.rows = rows;
        this.minLat = minLat;
        this.minLon = minLon;
        this.maxLat = maxLat;
        this.maxLon = maxLon;
        this.areaName = areaName;
        this.cropPoly = cropPoly;
        this.tileCount = tileCount;
        this.totalFeatures = totalFeatures;
        this.fileBytes = fileBytes;
        this.tiles = tiles;
    }

    public Tile getTile(int tx, int ty) {
        return tiles.get((((long) tx) << 32) | (ty & 0xffffffffL));
    }

    public boolean contains(double lat, double lon) {
        return lat >= minLat && lat <= maxLat && lon >= minLon && lon <= maxLon;
    }

    public double centerLat() {
        return (minLat + maxLat) * 0.5;
    }

    public double centerLon() {
        return (minLon + maxLon) * 0.5;
    }

    public double widthKm() {
        return CroSiteEngine.haversineM(centerLat(), minLon, centerLat(), maxLon) / 1000.0;
    }

    public double heightKm() {
        return CroSiteEngine.haversineM(minLat, minLon, maxLat, minLon) / 1000.0;
    }

    public static File storageFile(Context ctx) {
        return new File(ctx.getFilesDir(), FILE_NAME);
    }

    public static boolean exists(Context ctx) {
        File f = storageFile(ctx);
        return f.exists() && f.length() > 36;
    }

    public static void clear(Context ctx) {
        File f = storageFile(ctx);
        if (f.exists()) f.delete();
    }

    public static CroMapPack loadSaved(Context ctx) {
        File f = storageFile(ctx);
        if (!f.exists() || f.length() < 36) return null;
        try {
            return parseFile(f);
        } catch (Exception e) {
            return null;
        }
    }

    public static CroMapPack importFromUri(Context ctx, Uri uri) throws Exception {
        File tmp = new File(ctx.getFilesDir(), FILE_NAME + ".tmp");
        InputStream in = null;
        FileOutputStream out = null;
        try {
            in = ctx.getContentResolver().openInputStream(uri);
            if (in == null) throw new IllegalStateException("Cannot open file");
            out = new FileOutputStream(tmp);
            byte[] buf = new byte[16384];
            long total = 0L;
            int n;
            while ((n = in.read(buf)) > 0) {
                total += n;
                if (total > 24L * 1024L * 1024L) {
                    throw new IllegalArgumentException("Map file too large (>24 MB)");
                }
                out.write(buf, 0, n);
            }
            out.flush();
        } finally {
            try { if (in != null) in.close(); } catch (Exception ignored) {}
            try { if (out != null) out.close(); } catch (Exception ignored) {}
        }

        CroMapPack parsed;
        try {
            parsed = parseFile(tmp);
        } catch (Exception e) {
            tmp.delete();
            throw e;
        }
        File dst = storageFile(ctx);
        if (dst.exists()) dst.delete();
        if (!tmp.renameTo(dst)) {
            tmp.delete();
            throw new IllegalStateException("Failed saving map");
        }
        return parsed;
    }

    private static CroMapPack parseFile(File f) throws Exception {
        long fileLen = f.length();
        BufferedInputStream bis = new BufferedInputStream(new FileInputStream(f), 32768);
        bis.mark(4);
        int b0 = bis.read();
        int b1 = bis.read();
        bis.reset();

        InputStream rawIn = (b0 == 0x1f && b1 == 0x8b)
                ? new GZIPInputStream(bis, 32768)
                : bis;
        DataInputStream dis = new DataInputStream(new BufferedInputStream(rawIn, 32768));
        try {
            byte[] magic = new byte[4];
            dis.readFully(magic);
            if (magic[0] != 'C' || magic[1] != 'M' || magic[2] != 'A' || magic[3] != 'P') {
                throw new IllegalArgumentException("Not a valid .cmap file");
            }
            int ver = dis.readUnsignedByte();
            if (ver != 1 && ver != 2) throw new IllegalArgumentException("Unsupported CMAP version: " + ver);

            int zoom = dis.readUnsignedByte();
            int minX = dis.readInt();
            int minY = dis.readInt();
            int cols = dis.readUnsignedShort();
            int rows = dis.readUnsignedShort();
            float minLat = dis.readFloat();
            float minLon = dis.readFloat();
            float maxLat = dis.readFloat();
            float maxLon = dis.readFloat();
            dis.readInt(); // createdUnixSec
            int nameLen = dis.readUnsignedShort();
            String areaName = "Corvo Area";
            if (nameLen > 0 && nameLen <= 512) {
                byte[] nb = new byte[nameLen];
                dis.readFully(nb);
                areaName = new String(nb, StandardCharsets.UTF_8);
            } else if (nameLen > 512) {
                throw new IllegalArgumentException("Corrupt area name");
            }

            float[] cropPoly = null;
            if (ver >= 2) {
                int polyPts = dis.readUnsignedShort();
                if (polyPts > 512) throw new IllegalArgumentException("Corrupt crop polygon");
                if (polyPts >= 3) {
                    cropPoly = new float[polyPts * 2];
                    for (int pi = 0; pi < polyPts * 2; pi++) {
                        cropPoly[pi] = dis.readFloat();
                    }
                } else {
                    for (int pi = 0; pi < polyPts * 2; pi++) dis.readFloat();
                }
            }

            int tileCount = dis.readUnsignedShort();
            if (tileCount > 512) throw new IllegalArgumentException("Too many tiles: " + tileCount);
            HashMap<Long, Tile> tiles = new HashMap<Long, Tile>(Math.max(16, tileCount * 2));
            int totalFeatures = 0;

            for (int ti = 0; ti < tileCount; ti++) {
                int tx = dis.readInt();
                int ty = dis.readInt();
                int tz = dis.readUnsignedByte();
                int fCount = dis.readUnsignedShort();
                if (fCount > 40000) throw new IllegalArgumentException("Corrupt tile feature count");
                Feature[] feats = new Feature[fCount];
                for (int fi = 0; fi < fCount; fi++) {
                    int kind = dis.readUnsignedByte();
                    int flags = dis.readUnsignedByte();
                    int gtype = flags & 0x03;
                    String label = "";
                    if ((flags & 0x80) != 0) {
                        int ll = dis.readUnsignedByte();
                        if (ll > 0) {
                            byte[] lb = new byte[ll];
                            dis.readFully(lb);
                            label = new String(lb, StandardCharsets.UTF_8);
                        }
                    }
                    int rCount = dis.readUnsignedShort();
                    if (rCount > 4096) throw new IllegalArgumentException("Corrupt ring count");
                    short[][] rings = new short[rCount][];
                    for (int ri = 0; ri < rCount; ri++) {
                        int ptCount = dis.readUnsignedShort();
                        if (ptCount > 65535) throw new IllegalArgumentException("Corrupt point count");
                        short[] pts = new short[ptCount * 2];
                        for (int pi = 0; pi < ptCount * 2; pi++) {
                            pts[pi] = dis.readShort();
                        }
                        rings[ri] = pts;
                    }
                    feats[fi] = new Feature(kind, gtype, label, rings);
                    totalFeatures++;
                }
                long key = (((long) tx) << 32) | (ty & 0xffffffffL);
                tiles.put(key, new Tile(tx, ty, tz, feats));
            }
            return new CroMapPack(zoom, minX, minY, cols, rows,
                    minLat, minLon, maxLat, maxLon,
                    areaName, cropPoly, tileCount, totalFeatures, fileLen, tiles);
        } finally {
            try { dis.close(); } catch (Exception ignored) {}
        }
    }
}
